// Pages reads a small public endpoint file afresh, keeping invitations stable
// when the local tunnel changes. This file never carries access credentials.
let endpointCheckedAt=0;
async function refreshEndpoint(force=false){
  if(!location.hostname.endsWith('.github.io')||!force&&Date.now()-endpointCheckedAt<15000)return;
  endpointCheckedAt=Date.now();
  try{
    const url=new URL('./endpoint.json',location.href);url.searchParams.set('v',String(Date.now()));
    const response=await fetch(url,{cache:'no-store',credentials:'omit',signal:AbortSignal.timeout(8000)});
    if(response.ok){const config=await response.json(),u=new URL(config.apiBase);
      if(u.protocol==='https:'&&!u.username&&!u.password&&!u.port&&u.pathname==='/'&&!u.search&&!u.hash&&u.hostname.endsWith('.trycloudflare.com'))
        {window.LOVE_CONFIG={...(window.LOVE_CONFIG||{}),apiBase:u.origin,enabledPersonas:['self']};return u.origin;}
    }
  }catch{}
}
await refreshEndpoint(true);
const linkParams=new URLSearchParams(location.hash.slice(1)),key=linkParams.get('key')||'';
